// Entry point. Lives in the package root so that BOTH
//   rustc test5.rs
//   cargo build --release
// compile the exact same source. #[path] is resolved relative to the
// directory containing THIS file, which is the package root in both cases.
#[path = "src/indicators/mod.rs"]
mod indicators;

fn main() {
    // Accept and ignore any CLI args, exactly like the C++ binary.
    let _args: Vec<String> = std::env::args().collect();

    println!("{}", indicators::stub_ok());
    println!("{}", indicators::format::stub_ok());
    println!("{}", indicators::widgets::bar::stub_ok());
    // NOTE: indicators::format::never_called() is deliberately NOT called,
    // to observe whether dead_code fires on it.
}

// Plain `pub mod` declarations: these resolve relative to THIS file's
// directory (src/indicators/), so no further #[path] attributes are needed.
pub mod format;
pub mod widgets;

pub fn stub_ok() -> &'static str {
    "ok-root"
}

pub fn stub_ok() -> &'static str {
    "ok-format"
}

// Public API item the entry file never calls -- used to observe dead_code.
pub fn never_called() -> &'static str {
    "unused"
}

// Second level of nesting, again with no #[path]: resolves relative to
// src/indicators/widgets/.
pub mod bar;

