fn main() {
    // Edition-sensitive constructs:
    // 1. `dyn Trait` bare-trait-object lint differs 2015 vs 2018+
    // 2. array IntoIterator by value: 2021 only
    let a = [1u8, 2, 3];
    let s: u32 = a.into_iter().map(|x| x as u32).sum();
    // 3. uniform paths in `use`: `use indicators::format;` is 2018+ only
    use indicators::format;
    println!("{} {}", s, format::stub_ok());
}
EOF
cp /tmp/edtest.rs /tmp/pkgcheck/edtest.rs
echo "=== rustc with NO --edition flag (default) ==="
cd /tmp/pkgcheck && rustc edtest.rs -o /tmp/edtest_bin 2>&1 | head -40; echo "EXIT=${PIPESTATUS[0]}"

cd /tmp/pkgcheck && cat > usetest.rs <<'EOF'
#[path = "src/indicators/mod.rs"]
mod indicators;
fn main() {
    use indicators::format;          // uniform path: 2018+ only
    println!("{}", format::stub_ok());
}
EOF
echo "### A) bare rustc (default edition):"; rustc usetest.rs -o /tmp/u1 2>&1 | head -25
echo "### B) rustc --edition 2021:"; rustc --edition 2021 usetest.rs -o /tmp/u2 2>&1 | head -10; echo "  exit=${PIPESTATUS[0]}"
echo "### C) what edition is the default? probe via a 2018 keyword:"
printf 'fn main(){ let async_ = 1; println!("{}", async_); }\nfn r#try(){}\n' > ed2.rs
rustc ed2.rs -o /tmp/u3 2>&1 | head -20; echo "  exit=${PIPESTATUS[0]}"

